        if (msg.sender != projectAdmin) revert Unauthorized();
        if (newAdmin == address(0)) revert InvalidAdmin();

        address oldAdmin = projectAdmin;
        projectAdmin = newAdmin;
        emit ProjectAdminChanged(oldAdmin, newAdmin);
    }

