    // #### GETTERS ####
    ////////////////////////////////////////////////////////////////////////////////////////
    function sqrtPriceX96(CLSlot0 _packed) internal pure returns (uint160 _sqrtPriceX96) {
        assembly ("memory-safe") {
            _sqrtPriceX96 := and(MASK_160_BITS, _packed)
        }
